const pptxgen = require("pptxgenjs");

// ============================================================
// DESIGN SYSTEM — Midnight Executive (enterprise / data-forward)
// ============================================================
const COLORS = {
  navy: "1E2761",
  iceBlue: "CADCFC",
  white: "FFFFFF",
  slate: "4A5568",
  lightGray: "F7FAFC",
  accentTeal: "0D9488",
  accentCoral: "F96167",
  accentGold: "F9E795",
  darkNavy: "0F1535",
};

const FONTS = {
  header: "Trebuchet MS",
  body: "Calibri",
};

const pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.title = "1,001 Real-World Gen AI Use Cases from Google Cloud Customers";
pres.author = "Google Cloud / Enterprise Strategy";
pres.subject = "Generative AI Adoption Report";

// ============================================================
// HELPERS
// ============================================================
function makeShadow() {
  return {
    type: "outer",
    color: "000000",
    blur: 6,
    offset: 2,
    angle: 135,
    opacity: 0.12,
  };
}

function addTitleBlock(slide, title, subtitle, isDark = false) {
  const titleColor = isDark ? COLORS.white : COLORS.navy;
  const subColor = isDark ? COLORS.iceBlue : COLORS.slate;

  slide.addText(title, {
    x: 0.5,
    y: 0.35,
    w: 9,
    h: 0.7,
    fontSize: 32,
    fontFace: FONTS.header,
    bold: true,
    color: titleColor,
    align: "left",
    valign: "middle",
    margin: 0,
  });

  if (subtitle) {
    slide.addText(subtitle, {
      x: 0.5,
      y: 1.05,
      w: 9,
      h: 0.35,
      fontSize: 14,
      fontFace: FONTS.body,
      color: subColor,
      align: "left",
      valign: "middle",
      margin: 0,
    });
  }
}

function addFooter(slide, isDark = false) {
  const color = isDark ? "64748B" : "94A3B8";
  slide.addText("Source: Google Cloud Blog, October 2025", {
    x: 0.5,
    y: 5.35,
    w: 4,
    h: 0.2,
    fontSize: 9,
    fontFace: FONTS.body,
    color: color,
    align: "left",
    valign: "middle",
    margin: 0,
  });
  slide.addText("1,001 Real-World Gen AI Use Cases", {
    x: 6.5,
    y: 5.35,
    w: 3,
    h: 0.2,
    fontSize: 9,
    fontFace: FONTS.body,
    color: color,
    align: "right",
    valign: "middle",
    margin: 0,
  });
}

// ============================================================
// SLIDE 1 — TITLE COVER (dark)
// ============================================================
{
  const slide = pres.addSlide();
  slide.background = { color: COLORS.darkNavy };

  // Decorative accent bar left
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0,
    y: 0,
    w: 0.12,
    h: 5.625,
    fill: { color: COLORS.accentTeal },
  });

  // Large stat callouts background shapes
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5,
    y: 3.6,
    w: 2.8,
    h: 1.1,
    fill: { color: "1A237E", transparency: 60 },
    rectRadius: 0.08,
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 3.6,
    y: 3.6,
    w: 2.8,
    h: 1.1,
    fill: { color: "1A237E", transparency: 60 },
    rectRadius: 0.08,
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 6.7,
    y: 3.6,
    w: 2.8,
    h: 1.1,
    fill: { color: "1A237E", transparency: 60 },
    rectRadius: 0.08,
  });

  // Title
  slide.addText("1,001 Real-World Gen AI Use Cases", {
    x: 0.5,
    y: 1.2,
    w: 9,
    h: 0.9,
    fontSize: 44,
    fontFace: FONTS.header,
    bold: true,
    color: COLORS.white,
    align: "left",
    valign: "middle",
    margin: 0,
  });

  slide.addText("from Google Cloud Customers", {
    x: 0.5,
    y: 2.05,
    w: 9,
    h: 0.5,
    fontSize: 24,
    fontFace: FONTS.header,
    bold: false,
    color: COLORS.iceBlue,
    align: "left",
    valign: "middle",
    margin: 0,
  });

  // Subtitle / source line
  slide.addText(
    "Updated October 2025  ·  11 industries  ·  6 agent types  ·  10× growth from the original 101 entries",
    {
      x: 0.5,
      y: 2.6,
      w: 9,
      h: 0.3,
      fontSize: 13,
      fontFace: FONTS.body,
      color: "94A3B8",
      align: "left",
      valign: "middle",
      margin: 0,
    }
  );

  // Stat callouts
  slide.addText("1,001", {
    x: 0.5,
    y: 3.65,
    w: 2.8,
    h: 0.55,
    fontSize: 36,
    fontFace: FONTS.header,
    bold: true,
    color: COLORS.accentTeal,
    align: "center",
    valign: "middle",
    margin: 0,
  });
  slide.addText("Real-world use cases", {
    x: 0.5,
    y: 4.2,
    w: 2.8,
    h: 0.4,
    fontSize: 11,
    fontFace: FONTS.body,
    color: COLORS.iceBlue,
    align: "center",
    valign: "middle",
    margin: 0,
  });

  slide.addText("11", {
    x: 3.6,
    y: 3.65,
    w: 2.8,
    h: 0.55,
    fontSize: 36,
    fontFace: FONTS.header,
    bold: true,
    color: COLORS.accentTeal,
    align: "center",
    valign: "middle",
    margin: 0,
  });
  slide.addText("Industry verticals", {
    x: 3.6,
    y: 4.2,
    w: 2.8,
    h: 0.4,
    fontSize: 11,
    fontFace: FONTS.body,
    color: COLORS.iceBlue,
    align: "center",
    valign: "middle",
    margin: 0,
  });

  slide.addText("6", {
    x: 6.7,
    y: 3.65,
    w: 2.8,
    h: 0.55,
    fontSize: 36,
    fontFace: FONTS.header,
    bold: true,
    color: COLORS.accentTeal,
    align: "center",
    valign: "middle",
    margin: 0,
  });
  slide.addText("Agent types", {
    x: 6.7,
    y: 4.2,
    w: 2.8,
    h: 0.4,
    fontSize: 11,
    fontFace: FONTS.body,
    color: COLORS.iceBlue,
    align: "center",
    valign: "middle",
    margin: 0,
  });
}

// ============================================================
// SLIDE 2 — GROWTH TRAJECTORY (light)
// ============================================================
{
  const slide = pres.addSlide();
  slide.background = { color: COLORS.white };

  addTitleBlock(
    slide,
    "From 101 to 1,001: Gen AI Adoption Grew 10× in 18 Months",
    "April 2024 → October 2025",
    false
  );

  // Timeline bar background
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5,
    y: 2.0,
    w: 9,
    h: 0.18,
    fill: { color: "E2E8F0" },
  });

  // Progress fill (from left to right)
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5,
    y: 2.0,
    w: 9,
    h: 0.18,
    fill: { color: COLORS.accentTeal },
  });

  // Milestone circles
  slide.addShape(pres.shapes.OVAL, {
    x: 0.35,
    y: 1.87,
    w: 0.44,
    h: 0.44,
    fill: { color: COLORS.white },
    line: { color: COLORS.accentTeal, width: 3 },
  });
  slide.addShape(pres.shapes.OVAL, {
    x: 9.21,
    y: 1.87,
    w: 0.44,
    h: 0.44,
    fill: { color: COLORS.accentTeal },
    line: { color: COLORS.accentTeal, width: 3 },
  });

  // Labels below timeline
  slide.addText("Cloud Next '24", {
    x: 0.2,
    y: 2.35,
    w: 1.2,
    h: 0.25,
    fontSize: 12,
    fontFace: FONTS.body,
    bold: true,
    color: COLORS.navy,
    align: "center",
    valign: "middle",
    margin: 0,
  });
  slide.addText("April 2024", {
    x: 0.2,
    y: 2.58,
    w: 1.2,
    h: 0.2,
    fontSize: 10,
    fontFace: FONTS.body,
    color: COLORS.slate,
    align: "center",
    valign: "middle",
    margin: 0,
  });
  slide.addText("101 use cases", {
    x: 0.2,
    y: 2.78,
    w: 1.2,
    h: 0.2,
    fontSize: 10,
    fontFace: FONTS.body,
    color: COLORS.accentTeal,
    align: "center",
    valign: "middle",
    margin: 0,
  });

  slide.addText("October 2025 Update", {
    x: 8.6,
    y: 2.35,
    w: 1.5,
    h: 0.25,
    fontSize: 12,
    fontFace: FONTS.body,
    bold: true,
    color: COLORS.navy,
    align: "center",
    valign: "middle",
    margin: 0,
  });
  slide.addText("October 2025", {
    x: 8.6,
    y: 2.58,
    w: 1.5,
    h: 0.2,
    fontSize: 10,
    fontFace: FONTS.body,
    color: COLORS.slate,
    align: "center",
    valign: "middle",
    margin: 0,
  });
  slide.addText("1,001 use cases", {
    x: 8.6,
    y: 2.78,
    w: 1.5,
    h: 0.2,
    fontSize: 10,
    fontFace: FONTS.body,
    bold: true,
    color: COLORS.accentTeal,
    align: "center",
    valign: "middle",
    margin: 0,
  });

  // Big 10× callout
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 3.5,
    y: 3.3,
    w: 3.0,
    h: 1.3,
    fill: { color: COLORS.lightGray },
    rectRadius: 0.08,
    shadow: makeShadow(),
  });
  slide.addText("10×", {
    x: 3.5,
    y: 3.35,
    w: 3.0,
    h: 0.7,
    fontSize: 52,
    fontFace: FONTS.header,
    bold: true,
    color: COLORS.accentTeal,
    align: "center",
    valign: "middle",
    margin: 0,
  });
  slide.addText("Growth in real-world deployments", {
    x: 3.5,
    y: 4.05,
    w: 3.0,
    h: 0.4,
    fontSize: 12,
    fontFace: FONTS.body,
    color: COLORS.slate,
    align: "center",
    valign: "middle",
    margin: 0,
  });

  // Side annotation
  slide.addText(
    [
      { text: "400 new entries", options: { bold: true, breakLine: true } },
      { text: "added in the October 2025 update alone — reflecting accelerating enterprise adoption.", options: {} },
    ],
    {
      x: 7.0,
      y: 3.4,
      w: 2.5,
      h: 1.0,
      fontSize: 12,
      fontFace: FONTS.body,
      color: COLORS.slate,
      align: "left",
      valign: "top",
      margin: 0.05,
    }
  );

  addFooter(slide, false);
}

// ============================================================
// SLIDE 3 — INDUSTRY & AGENT TAXONOMY (light, matrix grid)
// ============================================================
{
  const slide = pres.addSlide();
  slide.background = { color: COLORS.white };

  addTitleBlock(
    slide,
    "11 Industries × 6 Agent Types: A Taxonomy of Enterprise Gen AI",
    "Structured framework for identifying and prioritizing gen AI opportunities",
    false
  );

  const industries = [
    "Automotive & Logistics",
    "Business & Professional Services",
    "Financial Services",
    "Healthcare & Life Sciences",
    "Hospitality & Travel",
    "Manufacturing, Industrial & Electronics",
    "Media, Marketing & Gaming",
    "Public Sector & Nonprofits",
    "Retail",
    "Technology",
    "Telecommunications",
  ];

  const agents = ["Customer", "Employee", "Creative", "Code", "Data", "Security"];

  const startX = 0.45;
  const startY = 1.6;
  const cellW = 1.48;
  const cellH = 0.32;

  // Agent header row
  agents.forEach((agent, i) => {
    slide.addShape(pres.shapes.RECTANGLE, {
      x: startX + 1.55 + i * cellW,
      y: startY,
      w: cellW,
      h: cellH,
      fill: { color: COLORS.navy },
    });
    slide.addText(agent, {
      x: startX + 1.55 + i * cellW,
      y: startY,
      w: cellW,
      h: cellH,
      fontSize: 10,
      fontFace: FONTS.body,
      bold: true,
      color: COLORS.white,
      align: "center",
      valign: "middle",
      margin: 0.02,
    });
  });

  // Industry column header
  slide.addShape(pres.shapes.RECTANGLE, {
    x: startX,
    y: startY,
    w: 1.55,
    h: cellH,
    fill: { color: COLORS.navy },
  });
  slide.addText("Industry Vertical", {
    x: startX,
    y: startY,
    w: 1.55,
    h: cellH,
    fontSize: 10,
    fontFace: FONTS.body,
    bold: true,
    color: COLORS.white,
    align: "center",
    valign: "middle",
    margin: 0.02,
  });

  // Grid rows
  industries.forEach((ind, row) => {
    const y = startY + cellH + row * cellH;
    const isAlt = row % 2 === 1;

    // Industry label cell
    slide.addShape(pres.shapes.RECTANGLE, {
      x: startX,
      y: y,
      w: 1.55,
      h: cellH,
      fill: { color: isAlt ? "F1F5F9" : COLORS.white },
      line: { color: "E2E8F0", width: 0.5 },
    });
    slide.addText(ind, {
      x: startX,
      y: y,
      w: 1.55,
      h: cellH,
      fontSize: 9,
      fontFace: FONTS.body,
      bold: true,
      color: COLORS.navy,
      align: "left",
      valign: "middle",
      margin: 0.04,
    });

    // Agent cells (dot markers)
    agents.forEach((_, col) => {
      slide.addShape(pres.shapes.RECTANGLE, {
        x: startX + 1.55 + col * cellW,
        y: y,
        w: cellW,
        h: cellH,
        fill: { color: isAlt ? "F1F5F9" : COLORS.white },
        line: { color: "E2E8F0", width: 0.5 },
      });
      // Small teal dot to indicate intersection
      slide.addShape(pres.shapes.OVAL, {
        x: startX + 1.55 + col * cellW + cellW / 2 - 0.06,
        y: y + cellH / 2 - 0.06,
        w: 0.12,
        h: 0.12,
        fill: { color: COLORS.accentTeal },
      });
    });
  });

  // Legend
  slide.addShape(pres.shapes.OVAL, {
    x: 0.5,
    y: 5.25,
    w: 0.12,
    h: 0.12,
    fill: { color: COLORS.accentTeal },
  });
  slide.addText("= Use cases documented in the 1,001 report", {
    x: 0.7,
    y: 5.2,
    w: 4,
    h: 0.22,
    fontSize: 10,
    fontFace: FONTS.body,
    color: COLORS.slate,
    align: "left",
    valign: "middle",
    margin: 0,
  });

  addFooter(slide, false);
}

// ============================================================
// SLIDE 4 — AUTOMOTIVE & LOGISTICS DEEP-DIVE (light, table)
// ============================================================
{
  const slide = pres.addSlide();
  slide.background = { color: COLORS.white };

  addTitleBlock(
    slide,
    "Automotive & Logistics: AI Agents From Cockpit to Curbside",
    "Representative use cases across Customer, Employee, and Code agent types",
    false
  );

  const tableData = [
    [
      { text: "Agent Type", options: { fill: { color: COLORS.navy }, color: COLORS.white, bold: true, fontSize: 11 } },
      { text: "Organization", options: { fill: { color: COLORS.navy }, color: COLORS.white, bold: true, fontSize: 11 } },
      { text: "Use Case & Outcome", options: { fill: { color: COLORS.navy }, color: COLORS.white, bold: true, fontSize: 11 } },
    ],
    [
      { text: "Customer", options: { fill: { color: "F1F5F9" }, bold: true, color: COLORS.navy, fontSize: 10 } },
      { text: "Mercedes-Benz", options: { fill: { color: "F1F5F9" }, color: COLORS.slate, fontSize: 10 } },
      { text: "MBUX Virtual Assistant powered by Gemini via Vertex AI enables natural driver conversations for navigation and POI", options: { fill: { color: "F1F5F9" }, color: COLORS.slate, fontSize: 10 } },
    ],
    [
      { text: "Customer", options: { bold: true, color: COLORS.navy, fontSize: 10 } },
      { text: "LUXGEN (Taiwan EV)", options: { color: COLORS.slate, fontSize: 10 } },
      { text: "AI agent on LINE answers customer questions via Vertex AI — reduced human CS workload by 30%", options: { color: COLORS.slate, fontSize: 10 } },
    ],
    [
      { text: "Customer", options: { fill: { color: "F1F5F9" }, bold: true, color: COLORS.navy, fontSize: 10 } },
      { text: "General Motors (OnStar)", options: { fill: { color: "F1F5F9" }, color: COLORS.slate, fontSize: 10 } },
      { text: "Virtual assistant with Google Cloud conversational AI recognizes speaker intent", options: { fill: { color: "F1F5F9" }, color: COLORS.slate, fontSize: 10 } },
    ],
    [
      { text: "Customer", options: { bold: true, color: COLORS.navy, fontSize: 10 } },
      { text: "Volkswagen of America", options: { color: COLORS.slate, fontSize: 10 } },
      { text: "myVW app virtual assistant lets drivers query owner's manuals; multimodal camera feature for dashboard indicators", options: { color: COLORS.slate, fontSize: 10 } },
    ],
    [
      { text: "Customer", options: { fill: { color: "F1F5F9" }, bold: true, color: COLORS.navy, fontSize: 10 } },
