    [
      { text: "Employee", options: { bold: true, color: COLORS.navy, fontSize: 10 } },
      { text: "Toyota", options: { color: COLORS.slate, fontSize: 10 } },
      { text: "AI platform on Google Cloud enables factory workers to build and deploy ML models — 10,000+ man-hours/year saved", options: { color: COLORS.slate, fontSize: 10 } },
    ],
    [
      { text: "Employee", options: { fill: { color: "F1F5F9" }, bold: true, color: COLORS.navy, fontSize: 10 } },
      { text: "Uber", options: { fill: { color: "F1F5F9" }, color: COLORS.slate, fontSize: 10 } },
      { text: "AI agents summarize CS communications and surface prior interaction context", options: { fill: { color: "F1F5F9" }, color: COLORS.slate, fontSize: 10 } },
    ],
    [
      { text: "Employee", options: { bold: true, color: COLORS.navy, fontSize: 10 } },
      { text: "Rivian", options: { color: COLORS.slate, fontSize: 10 } },
      { text: "Gemini in Google Workspace for instant research, accelerated learning, and rapid skill acquisition", options: { color: COLORS.slate, fontSize: 10 } },
