    ],
    [
      { text: "Code", options: { bold: true, color: COLORS.navy, fontSize: 10 } },
      { text: "Renault Group (Ampere)", options: { color: COLORS.slate, fontSize: 10 } },
      { text: "Enterprise Gemini Code Assist understands company code base, standards, and conventions for EV software developer productivity", options: { color: COLORS.slate, fontSize: 10 } },
    ],
