    fontSize: 40,
    fontFace: FONTS.header,
    bold: true,
    color: COLORS.accentTeal,
    align: "left",
    valign: "middle",
    margin: 0,
  });
  slide.addText("ROI anticipated by Mercari", {
    x: 0.7,
    y: 2.3,
    w: 3.9,
    h: 0.25,
    fontSize: 13,
    fontFace: FONTS.body,
    bold: true,
    color: COLORS.navy,
    align: "left",
    valign: "middle",
    margin: 0,
