  slide.addText("Japan's largest online marketplace; also reducing employee workloads by 20% through AI-powered customer service.", {
    x: 0.7,
    y: 2.55,
    w: 3.9,
    h: 0.5,
    fontSize: 11,
    fontFace: FONTS.body,
    color: COLORS.slate,
