// ============================================================
// HELPERS
// ============================================================
function makeShadow() {
  return {
    type: "outer",
    color: "000000",
    blur: 6,
    offset: 2,
    angle: 135,
    opacity: 0.12,
  };
}

function addTitleBlock(slide, title, subtitle, isDark = false) {
  const titleColor = isDark ? COLORS.white : COLORS.navy;
  const subColor = isDark ? COLORS.iceBlue : COLORS.slate;

  slide.addText(title, {
    x: 0.5,
    y: 0.35,
    w: 9,
    h: 0.7,
    fontSize: 32,
    fontFace: FONTS.header,
    bold: true,
    color: titleColor,
    align: "left",
    valign: "middle",
    margin: 0,
  });

  if (subtitle) {
    slide.addText(subtitle, {
      x: 0.5,
      y: 1.05,
      w: 9,
      h: 0.35,
      fontSize: 14,
      fontFace: FONTS.body,
      color: subColor,
      align: "left",
      valign: "middle",
      margin: 0,
    });
  }
}

