// ============================================================
// SLIDE 3 — INDUSTRY & AGENT TAXONOMY (light, matrix grid)
// ============================================================
{
  const slide = pres.addSlide();
  slide.background = { color: COLORS.white };

  addTitleBlock(
    slide,
    "11 Industries × 6 Agent Types: A Taxonomy of Enterprise Gen AI",
    "Structured framework for identifying and prioritizing gen AI opportunities",
    false
  );

  const industries = [
    "Automotive & Logistics",
    "Business & Professional Services",
    "Financial Services",
    "Healthcare & Life Sciences",
    "Hospitality & Travel",
    "Manufacturing, Industrial & Electronics",
    "Media, Marketing & Gaming",
    "Public Sector & Nonprofits",
    "Retail",
    "Technology",
    "Telecommunications",
  ];

  const agents = ["Customer", "Employee", "Creative", "Code", "Data", "Security"];

  const startX = 0.45;
  const startY = 1.55;
  const cellW = 1.48;
  const cellH = 0.30;

  // Agent header row
  agents.forEach((agent, i) => {
    slide.addShape(pres.shapes.RECTANGLE, {
      x: startX + 1.55 + i * cellW,
      y: startY,
      w: cellW,
      h: cellH,
      fill: { color: COLORS.navy },
    });
    slide.addText(agent, {
      x: startX + 1.55 + i * cellW,
      y: startY,
      w: cellW,
      h: cellH,
      fontSize: 10,
      fontFace: FONTS.body,
      bold: true,
      color: COLORS.white,
      align: "center",
      valign: "middle",
      margin: 0.02,
    });
  });

  // Industry column header
  slide.addShape(pres.shapes.RECTANGLE, {
    x: startX,
    y: startY,
    w: 1.55,
    h: cellH,
    fill: { color: COLORS.navy },
  });
  slide.addText("Industry Vertical", {
    x: startX,
    y: startY,
    w: 1.55,
    h: cellH,
    fontSize: 10,
    fontFace: FONTS.body,
    bold: true,
    color: COLORS.white,
    align: "center",
    valign: "middle",
    margin: 0.02,
  });

  // Grid rows
  industries.forEach((ind, row) => {
    const y = startY + cellH + row * cellH;
    const isAlt = row % 2 === 1;

    // Industry label cell
    slide.addShape(pres.shapes.RECTANGLE, {
      x: startX,
      y: y,
      w: 1.55,
      h: cellH,
      fill: { color: isAlt ? "F1F5F9" : COLORS.white },
      line: { color: "E2E8F0", width: 0.5 },
    });
    slide.addText(ind, {
      x: startX,
      y: y,
      w: 1.55,
      h: cellH,
      fontSize: 9,
      fontFace: FONTS.body,
      bold: true,
      color: COLORS.navy,
      align: "left",
      valign: "middle",
      margin: 0.04,
    });

    // Agent cells (dot markers)
    agents.forEach((_, col) => {
      slide.addShape(pres.shapes.RECTANGLE, {
        x: startX + 1.55 + col * cellW,
        y: y,
        w: cellW,
        h: cellH,
        fill: { color: isAlt ? "F1F5F9" : COLORS.white },
        line: { color: "E2E8F0", width: 0.5 },
      });
      // Small teal dot to indicate intersection
      slide.addShape(pres.shapes.OVAL, {
        x: startX + 1.55 + col * cellW + cellW / 2 - 0.06,
        y: y + cellH / 2 - 0.06,
        w: 0.12,
        h: 0.12,
        fill: { color: COLORS.accentTeal },
      });
    });
  });

  // Legend
  slide.addShape(pres.shapes.OVAL, {
    x: 0.5,
    y: 5.05,
    w: 0.12,
    h: 0.12,
    fill: { color: COLORS.accentTeal },
  });
  slide.addText("= Use cases documented in the 1,001 report", {
    x: 0.7,
    y: 5.0,
    w: 4,
    h: 0.22,
    fontSize: 10,
    fontFace: FONTS.body,
    color: COLORS.slate,
    align: "left",
    valign: "middle",
    margin: 0,
  });

  addFooter(slide, false);
}

